PAYLOAD=json.loads("{\"src/katarina/monitoring/pair_activity.py\":\"\\\"\\\"\\\"Pair identifiers and lifecycle timestamps only; never quotes or account fields.\\\"\\\"\\\"\\nfrom datetime import datetime, timezone\\nimport json\\nfrom pathlib import Path\\nimport re\\n\\nPHASES={'SENSORS','HISTORY','TECHNICAL','VALIDATE','VALIDATE3'}|{\\n    'TEST_'+family+'_H'+str(h) for family in ('MOMENTUM','REVERSION','BREAKOUT') for h in (4,12,24)}\\nSTATES={'STARTED','DONE','FAILED','IDLE'}\\n\\n\\ndef _read(path):\\n    try:\\n        with path.open('rb') as f:raw=f.read(2_000_001)\\n        v=json.loads(raw) if len(raw)<=2_000_000 else {}\\n        return v if isinstance(v,dict) else {}\\n    except (OSError,ValueError,TypeError):return {}\\n\\n\\ndef _fresh(stamp,now,seconds=180):\\n    try:\\n        t=datetime.fromisoformat(stamp.replace('Z','+00:00'))\\n        return t.tzinfo is not None and -30<=(now-t).total_seconds()<=seconds\\n    except (AttributeError,ValueError,TypeError):return False\\n\\n\\ndef symbol(value):\\n    return value if isinstance(value,str) and re.fullmatch(r'[A-Za-z][A-Za-z0-9_.#-]{0,31}',value) else None\\n\\n\\ndef read_pair_activity(root,pid,*,allowed,now=None):\\n    empty={'status':'NOT_ATTESTED','symbols':[],'events':[],'active':[]}\\n    if not allowed or type(pid) is not int or pid<=0:return empty\\n    root=Path(root);now=now or datetime.now(timezone.utc);raw=_read(root/'runtime-activity.json')\\n    events=raw.get('events',[])\\n    if raw.get('pid')!=pid or not isinstance(events,list) or not events or not isinstance(events[-1],dict) or not _fresh(events[-1].get('at_utc'),now):return empty\\n    def clean(e):\\n        if not isinstance(e,dict):return None\\n        pair=symbol(e.get('symbol'))\\n        if not pair or e.get('phase') not in PHASES or e.get('state') not in STATES or type(e.get('seq')) is not int or not 1<=e['seq']<=1000000 or not _fresh(e.get('at_utc'),now):return None\\n        return {k:e[k] for k in ('symbol','phase','state','seq','at_utc')}\\n    rows=[c for e in events[-80:] if (c:=clean(e))]\\n    active=[c for e in raw.get('active',[])[:24] if (c:=clean(e)) and c['state']=='STARTED'] if isinstance(raw.get('active',[]),list) else []\\n    latest=_read(root/'latest.json');cards=latest.get('symbols',{})\\n    scanned=sorted(s for s,c in cards.items() if symbol(s) and isinstance(c,dict))[:64] if isinstance(cards,dict) and _fresh(latest.get('observed_at_utc'),now) else []\\n    names=sorted(set(scanned)|{e['symbol'] for e in rows+active})[:64]\\n    return dict(status='OBSERVED',pid=pid,as_of_utc=now.isoformat(),symbols=names,\\n                scan_observation_utc=latest.get('observed_at_utc') if scanned else None,\\n                events=rows,active=active,source='VPS_PAIR_LIFECYCLE',prices_included=False)\\n\",\"src/katarina/monitoring/mt5_dashboard.py\":\"\\\"\\\"\\\"Local-only MT5 dashboard transport. Display never grants execution rights.\\\"\\\"\\\"\\nfrom katarina.monitoring.snapshot_io import replace_snapshot\\nfrom datetime import datetime, timezone\\nimport json\\nimport os\\nfrom pathlib import Path\\nimport time\\nimport threading\\n\\n_WRITE_LOCK=threading.Lock()\\n\\n\\ndef dashboard_execution(root,status,now):\\n    \\\"\\\"\\\"Read E01 heartbeat separately; never renew its decision or permission age.\\\"\\\"\\\"\\n    from katarina.monitoring.worker_runtime import _read, _fresh\\n    root=Path(root);clock=datetime.fromtimestamp(now,timezone.utc)\\n    executor=_read(root/'demo-forward/executor.json')\\n    demo=status.get('demo_forward') or {}\\n    pid=executor.get('pid')\\n    independent=(executor.get('mode')=='DEMO' and executor.get('independent') is True\\n                 and type(pid) is int and pid>0 and _fresh(executor,clock)\\n                 and executor.get('status') in ('STARTING','RUNNING','AUDIT_ONLY','RETRY_PENDING'))\\n    if independent:\\n        decision=_read(root/'demo-forward/status.json')\\n        demo=decision if decision.get('pid')==pid and _fresh(decision,clock) else {}\\n        return demo,executor.get('as_of_utc'),True\\n    # Once independent mode is selected, stale E01 must never fall back to a stale inline owner.\\n    if (root/'demo-forward/independent.enabled').exists() or executor.get('independent') is True:\\n        return {},None,False\\n    return demo,demo.get('as_of_utc'),demo.get('pid')==status.get('pid')\\n\\n\\ndef publish_mt5_dashboard(root, status, config, *, target=None, now=None):\\n    now=time.time() if now is None else now\\n    if target is None:\\n        if os.name!='nt':return False\\n        base=os.environ.get('APPDATA')\\n        if not base:return False\\n        target=Path(base)/'MetaQuotes/Terminal/Common/Files/Katarina/owner-status.tsv'\\n    target=Path(target);root=Path(root)\\n    demo,executor_stamp,executor_bound=dashboard_execution(root,status,now);doctor=status.get('network_doctor') or {}\\n    def age(value):\\n        try:return max(0,int(now-datetime.fromisoformat(value).timestamp()))\\n        except (TypeError,ValueError):return 999999\\n    values=[1,int(now),status['pid'],status['status'],status.get('successful_cycles',0),\\n            status.get('background_workers',0),status.get('received_market_data_symbols',0),\\n            demo.get('execution_permission','UNKNOWN'),demo.get('status','PENDING'),\\n            demo.get('entry_decisions',0),demo.get('closed_outcomes',0),doctor.get('status','PENDING'),\\n            config.expected_login,config.expected_server,\\n            int((root/'continuous.stop').exists()),age(executor_stamp),\\n            int(executor_bound)]\\n    # Private local account binding only. Never published via dashboard APIs.\\n    raw='\\\\t'.join(str(x).replace('\\\\t',' ').replace('\\\\r',' ').replace('\\\\n',' ') for x in values)+'\\\\n'\\n    try:\\n        target.parent.mkdir(parents=True,exist_ok=True)\\n        with _WRITE_LOCK:\\n            temp=target.with_suffix('.tmp');temp.write_text(raw,encoding='ascii');replace_snapshot(temp,target)\\n        return True\\n    except (OSError,UnicodeError):return False\\n\\n\\nclass DashboardHeartbeat:\\n    \\\"\\\"\\\"Actual process liveness; never refreshes market/decision timestamps.\\\"\\\"\\\"\\n    def __init__(self,root,config,status,*,target=None):\\n        import threading\\n        self.root=root;self.config=config;self.status=status;self.target=target\\n        self.owner=threading.current_thread();self.stop=threading.Event()\\n        self.thread=threading.Thread(target=self.run,name='mt5-dashboard-heartbeat',daemon=True)\\n    def start(self):self.thread.start();return self\\n    def tick(self):\\n        status=dict(self.status())\\n        if not self.owner.is_alive():status['status']='BLOCKED'\\n        return publish_mt5_dashboard(self.root,status,self.config,target=self.target)\\n    def run(self):\\n        while not self.stop.is_set():\\n            try:self.tick()\\n            except Exception:pass # Display failure cannot interrupt the owner.\\n            self.stop.wait(5)\\n    def close(self):self.stop.set();self.thread.join(timeout=2)\\n\\n\",\"tests/unit/test_pair_activity.py\":\"from datetime import datetime,timezone,timedelta\\nimport json\\nfrom pathlib import Path\\nimport tempfile\\nimport unittest\\nfrom katarina.monitoring.pair_activity import read_pair_activity\\n\\nclass PairActivityTests(unittest.TestCase):\\n def test_parallel_pair_routes_privacy_and_process_binding(self):\\n  with tempfile.TemporaryDirectory() as d:\\n   r=Path(d);now=datetime.now(timezone.utc);s=now.isoformat()\\n   e=lambda pair,phase,seq:dict(symbol=pair,phase=phase,state='STARTED',seq=seq,at_utc=s,price=100,login='PRIVATE_SENTINEL')\\n   events=[e('XAUUSD.vx','TEST_MOMENTUM_H4',1),e('EURUSD.vx','TEST_BREAKOUT_H4',2)]\\n   (r/'runtime-activity.json').write_text(json.dumps(dict(pid=7,events=events,active=events)))\\n   (r/'latest.json').write_text(json.dumps(dict(observed_at_utc=s,symbols={'USDJPY.vx':{'bid':10,'account':'PRIVATE_SENTINEL'}})))\\n   out=read_pair_activity(r,7,allowed=True,now=now)\\n   self.assertEqual(len(out['active']),2);self.assertEqual(len(out['symbols']),3)\\n   self.assertNotIn('PRIVATE_SENTINEL',json.dumps(out));self.assertNotIn('price\\\"',json.dumps(out));self.assertNotIn('bid',json.dumps(out))\\n   self.assertEqual(read_pair_activity(r,8,allowed=True,now=now)['status'],'NOT_ATTESTED')\\n   self.assertEqual(read_pair_activity(r,7,allowed=False,now=now)['events'],[])\\n   self.assertEqual(read_pair_activity(r,7,allowed=True,now=now+timedelta(seconds=181))['symbols'],[])\\n\",\"tests/unit/test_mt5_dashboard_executor.py\":\"from datetime import datetime,timezone,timedelta\\nimport json\\nfrom pathlib import Path\\nfrom types import SimpleNamespace\\nimport tempfile\\nimport unittest\\nfrom katarina.monitoring.mt5_dashboard import publish_mt5_dashboard\\n\\nclass Mt5ExecutorTests(unittest.TestCase):\\n def test_independent_pid_and_stale_rejection_without_permission_renewal(self):\\n  with tempfile.TemporaryDirectory() as d:\\n   r=Path(d);p=r/'demo-forward';p.mkdir();now=datetime.now(timezone.utc);stamp=now.isoformat();old=(now-timedelta(seconds=200)).isoformat()\\n   (p/'executor.json').write_text(json.dumps(dict(pid=99,independent=True,mode='DEMO',status='RUNNING',as_of_utc=stamp)))\\n   (p/'status.json').write_text(json.dumps(dict(pid=99,as_of_utc=stamp,status='WAIT_STRATEGY_SIGNAL',execution_permission='DEMO_ORDER_PERMISSION_ON')))\\n   status=dict(pid=7,status='WAITING',demo_forward={'pid':7,'as_of_utc':old})\\n   dest=r/'out.tsv';cfg=SimpleNamespace(expected_login=123,expected_server='test')\\n   def fields():\\n    self.assertTrue(publish_mt5_dashboard(r,status,cfg,target=dest,now=now.timestamp()));return dest.read_text().strip().split('\\\\t')\\n   v=fields();self.assertEqual(len(v),17);self.assertEqual(v[16],'1');self.assertEqual(v[15],'0');self.assertEqual(v[8],'WAIT_STRATEGY_SIGNAL')\\n   (p/'status.json').write_text(json.dumps(dict(pid=123,as_of_utc=stamp,status='WRONG_ACCOUNT',execution_permission='DEMO_ORDER_PERMISSION_ON')))\\n   v=fields();self.assertEqual(v[16],'1');self.assertEqual(v[7],'UNKNOWN');self.assertEqual(v[8],'PENDING')\\n   (p/'executor.json').write_text(json.dumps(dict(pid=99,independent=True,mode='DEMO',status='RUNNING',as_of_utc=old)))\\n   v=fields();self.assertEqual(v[16],'0');self.assertEqual(v[15],'999999');self.assertEqual(v[7],'UNKNOWN')\\n\",\"expected_mt5\":\"\\\"\\\"\\\"Local-only MT5 dashboard transport. Display never grants execution rights.\\\"\\\"\\\"\\nfrom katarina.monitoring.snapshot_io import replace_snapshot\\nfrom datetime import datetime\\nimport os\\nfrom pathlib import Path\\nimport time\\nimport threading\\n\\n_WRITE_LOCK=threading.Lock()\\n\\n\\ndef publish_mt5_dashboard(root, status, config, *, target=None, now=None):\\n    now=time.time() if now is None else now\\n    if target is None:\\n        if os.name!='nt':return False\\n        base=os.environ.get('APPDATA')\\n        if not base:return False\\n        target=Path(base)/'MetaQuotes/Terminal/Common/Files/Katarina/owner-status.tsv'\\n    target=Path(target);root=Path(root)\\n    demo=status.get('demo_forward') or {};doctor=status.get('network_doctor') or {}\\n    def age(value):\\n        try:return max(0,int(now-datetime.fromisoformat(value).timestamp()))\\n        except (TypeError,ValueError):return 999999\\n    values=[1,int(now),status['pid'],status['status'],status.get('successful_cycles',0),\\n            status.get('background_workers',0),status.get('received_market_data_symbols',0),\\n            demo.get('execution_permission','UNKNOWN'),demo.get('status','PENDING'),\\n            demo.get('entry_decisions',0),demo.get('closed_outcomes',0),doctor.get('status','PENDING'),\\n            config.expected_login,config.expected_server,\\n            int((root/'continuous.stop').exists()),age(demo.get('as_of_utc')),\\n            int(demo.get('pid')==status['pid'])]\\n    # Private local account binding only. Never published via dashboard APIs.\\n    raw='\\\\t'.join(str(x).replace('\\\\t',' ').replace('\\\\r',' ').replace('\\\\n',' ') for x in values)+'\\\\n'\\n    try:\\n        target.parent.mkdir(parents=True,exist_ok=True)\\n        with _WRITE_LOCK:\\n            temp=target.with_suffix('.tmp');temp.write_text(raw,encoding='ascii');replace_snapshot(temp,target)\\n        return True\\n    except (OSError,UnicodeError):return False\\n\\n\\nclass DashboardHeartbeat:\\n    \\\"\\\"\\\"Actual process liveness; never refreshes market/decision timestamps.\\\"\\\"\\\"\\n    def __init__(self,root,config,status,*,target=None):\\n        import threading\\n        self.root=root;self.config=config;self.status=status;self.target=target\\n        self.owner=threading.current_thread();self.stop=threading.Event()\\n        self.thread=threading.Thread(target=self.run,name='mt5-dashboard-heartbeat',daemon=True)\\n    def start(self):self.thread.start();return self\\n    def tick(self):\\n        status=dict(self.status())\\n        if not self.owner.is_alive():status['status']='BLOCKED'\\n        return publish_mt5_dashboard(self.root,status,self.config,target=self.target)\\n    def run(self):\\n        while not self.stop.is_set():\\n            try:self.tick()\\n            except Exception:pass # Display failure cannot interrupt the owner.\\n            self.stop.wait(5)\\n    def close(self):self.stop.set();self.thread.join(timeout=2)\\n\",\"expected_public\":\"\\\"\\\"\\\"Reconstruct a technical-only, freshness-checked view without opening broker or memory.\\\"\\\"\\\"\\nfrom pathlib import Path\\nimport json\\nfrom katarina.intelligence.runtime_evidence import read_runtime\\nfrom katarina.monitoring.agent_projection import project_agent_board\\nfrom katarina.monitoring.activity_trace import read_activity\\nfrom katarina.adapters.owner_dialog_server import public_dashboard_snapshot\\n\\ndef build_public_runtime(root):\\n    root=Path(root)\\n    try:\\n        status=json.loads((root/'continuous-status.json').read_text(encoding='utf-8'))\\n    except (OSError,ValueError):\\n        status={}\\n    evidence=read_runtime(root)\\n    board=project_agent_board(evidence,delivery=status.get('delivery','UNVERIFIED'))\\n    activity=read_activity(root)\\n    pid=status.get('pid')\\n    board['current_process_pid']=pid\\n    market_process_matches=evidence.get('operational',{}).get('snapshot_pid')==pid\\n    board['snapshot_process_matches']=bool(type(pid) is int and activity.get('pid')==pid and activity.get('fresh'))\\n    if not market_process_matches:\\n        board['result']='BLOCKED'\\n    if status.get('status') in ('STOPPED','BLOCKED'):\\n        board['result']='BLOCKED'\\n    board['model']={'configured':status.get('model_configured') is True,\\n                    'telemetry':status.get('model_telemetry',{})}\\n    board['activity']=activity\\n    public = public_dashboard_snapshot({'agent_board':board})\\n    from katarina.monitoring.learning_evidence import read_learning\\n    from katarina.monitoring.public_research import read_public_research\\n    allowed = board['snapshot_process_matches'] and board.get('result') == 'SNAPSHOT_PASS'\\n    research_allowed = bool(board['snapshot_process_matches'] and status.get('delivery') == 'DISABLED'\\n        and status.get('live_execution_authorized') is False and status.get('orders_submitted') == 0\\n        and status.get('status') in ('WAITING','OBSERVING','DEGRADED'))\\n    # Sensor completeness and persisted research provenance are separate attestations.\\n    try:\\n        with (root/'latest.json').open('rb') as stream:\\n            raw=stream.read(2_000_001)\\n        observation_stamp=json.loads(raw)['observed_at_utc'] if len(raw)<=2_000_000 else None\\n    except (OSError,ValueError,KeyError):\\n        observation_stamp=None\\n    graph, entries = read_public_research(root,observation_stamp) if research_allowed else (\\n        {'schema_version':1,'nodes':[],'edges':[],'status':'NOT_ATTESTED'},\\n        {'status':'NOT_ATTESTED','positions':[]})\\n    if research_allowed and graph.get('status')=='NOT_ATTESTED':\\n        from katarina.monitoring.public_research import worker_research_runs,graph_from_report\\n        runs=worker_research_runs(root)\\n        if runs:graph=graph_from_report({'continuous_research_lab':{'recent':runs}})\\n    public_board=public['agent_board']\\n    # Process activity, market completeness and learning are distinct evidence scopes.\\n    from datetime import datetime, timezone\\n    try:\\n        heartbeat_age=(datetime.now(timezone.utc)-datetime.fromisoformat(status['heartbeat_utc'])).total_seconds()\\n    except (KeyError,ValueError,TypeError):\\n        heartbeat_age=float('inf')\\n    public_board['telemetry_verified']=bool(research_allowed and status.get('production_execution') is False\\n                                           and (-30<=heartbeat_age<=180 or activity.get('fresh') is True))\\n    public_board['market_snapshot_verified']=board.get('result')=='SNAPSHOT_PASS'\\n    public_board['sensor_blockers']=evidence.get('blockers',[])\\n    public_board['learning']=(read_learning(root,observation_utc=observation_stamp)\\n                              if public_board['telemetry_verified'] else {'status':'NOT_ATTESTED'})\\n    from katarina.monitoring.research_growth import read_growth\\n    public_board['research_growth']=read_growth(root,pid) if research_allowed else {'status':'NOT_ATTESTED'}\\n    public_board['research_graph']=graph\\n    from katarina.intelligence.research_reports import read_reports\\n    public_board['research_reports']=read_reports(root,pid) if research_allowed else {'status':'NOT_ATTESTED'}\\n    from katarina.monitoring.research_lab_status import read_lab_status\\n    public_board['research_lab'] = read_lab_status(root) if research_allowed else {'status':'NOT_ATTESTED'}\\n    from katarina.intelligence.data_recovery import read_recovery\\n    public_board['research_lab']['recovery']=read_recovery(root,pid) if research_allowed else {'status':'NOT_ATTESTED'}\\n    public_board['research_source_verified'] = research_allowed and graph.get('status') != 'NOT_ATTESTED'\\n    public_board['entries']=entries\\n    public_board['market_symbols']=None\\n    public_board['operational']={}\\n    public_board['learning'].pop('no_signal_observations',None)\\n    trace=public_board['activity']\\n    trace['events']=[{k:e[k] for k in ('seq','at_utc','phase','state')} for e in trace['events']]\\n    trace['current']=trace['events'][-1] if trace['events'] else None\\n    from katarina.monitoring.worker_runtime import read_worker_runtime\\n    public_board['worker_runtime']=read_worker_runtime(root,pid)\\n    public_board['public_scope']='RESEARCH_GRAPH_AND_ENTRY_ONLY'\\n    return public\\n\"}")
